package com.phatjam98.elasticprotos.engine;

/**
 * The outcome of a single-document write.
 *
 * @param index the concrete index written to
 * @param id the document id, generated by the engine when none was given
 * @param result {@code created}, {@code updated}, {@code deleted} or {@code noop}
 * @param version the document version
 * @param seqNo the sequence number of the write, for a later conditional write, or null when the
 *     engine did not report one
 * @param primaryTerm the primary term of the write, or null when the engine did not report one
 */
public record IndexResult(String index, String id, String result, long version, Long seqNo,
    Long primaryTerm) {

  /**
   * A result without a sequence number and primary term.
   *
   * @param index the concrete index written to
   * @param id the document id
   * @param result what happened
   * @param version the document version
   */
  public IndexResult(String index, String id, String result, long version) {
    this(index, id, result, version, null, null);
  }
}
